using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "RighteousConjurationCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Orion/RighteousConjurationCustomDescription", order = 0)]
public class RighteousConjurationCustomDescription : CustomBattleActionDescription
{
	[SerializeField]
	private ConjureAction conjureAction;

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string firstArgument = this.conjureAction.GetActionDescription(EffectsValues.NO_VALUE).RemoveLast();
		ConjureAction conjureAction = battleAction as ConjureAction;
		return (conjureAction.EnableBattleActionBeforeConjure ? (conjureAction.BattleActionBeforeConjure.GetActionDescription(GetAmountWithoutEquation(amountModified)) + "\n") : "") + base.localizationManager.GetLocalizedWhereX(firstArgument, y: false, Smart.Format(GetRawLocalizedDescription(battleAction), base.localizationManager.GetLocalizedRoundedUp()));
	}
}
